package com.example.kyrgyzkeyboard.data.repository

import android.content.Context
import com.example.kyrgyzkeyboard.data.local.DictionaryDao
import com.example.kyrgyzkeyboard.data.model.WordEntity

/**
 * 词库仓库：对 [DictionaryDao] 的薄封装。
 *
 * 所有方法为 suspend，调度器由调用方（ViewModel）负责。
 */
class DictionaryRepository(private val dao: DictionaryDao) {

    /** 新增词条；返回新生成的主键 id。 */
    suspend fun addWord(
        word: String,
        pinyin: String? = null,
        meaning: String? = null,
        category: String = "常用"
    ): Long {
        val entity = WordEntity(
            word = word,
            pinyin = pinyin,
            meaning = meaning,
            category = category
        )
        return dao.insert(entity)
    }

    /** 编辑已有词条。 */
    suspend fun updateWord(word: WordEntity) = dao.update(word)

    /** 获取全部词条。 */
    suspend fun getAllWords(): List<WordEntity> = dao.getAll()

    /** 词条总数。 */
    suspend fun count(): Int = dao.count()

    /** 全部分类（去重）。 */
    suspend fun categories(): List<String> = dao.categories()

    /** 首启把 assets 种子词表灌入 Room（幂等，按种子版本判断）。 */
    suspend fun seedIfNeeded(context: Context) = DictionarySeeder.seedIfNeeded(context, dao)

    /** 搜索：空串返回全量。 */
    suspend fun searchWords(query: String): List<WordEntity> {
        val trimmed = query.trim()
        return if (trimmed.isEmpty()) dao.getAll() else dao.search(trimmed)
    }

    /** 按 id 删除。 */
    suspend fun deleteWord(id: Long) = dao.delete(id)

    /** 记录一次使用（频次 +1）。 */
    suspend fun recordUsage(id: Long) = dao.incrementFrequency(id)
}
